package org.sleepwell.app;

import org.junit.Test;
import static org.junit.Assert.*;

public class AutomaticTransitionTest {
    @Test public void repeatedCallbacksStartOneRecordingOnly(){int[] records={0};AutomaticTransition t=new AutomaticTransition(new AutomaticSleep(AutomaticSleep.Mode.STILLNESS,0,0),()->records[0]++);for(long at=0;at<=AutomaticSleep.QUIET_REQUIRED;at+=200)t.sample(at,.01,false);assertEquals(0,records[0]);t.tick(AutomaticSleep.QUIET_REQUIRED,false);for(int n=0;n<100;n++){t.sample(AutomaticSleep.QUIET_REQUIRED+n,.01,false);t.tick(AutomaticSleep.QUIET_REQUIRED+n,false);}assertEquals(1,records[0]);}
    @Test public void cancelBetweenQualifyingSampleAndTickPreventsRecording(){int[] records={0};AutomaticTransition t=new AutomaticTransition(new AutomaticSleep(AutomaticSleep.Mode.STILLNESS,0,0),()->records[0]++);for(long at=0;at<=AutomaticSleep.QUIET_REQUIRED;at+=200)t.sample(at,.01,false);t.cancel();t.tick(AutomaticSleep.QUIET_REQUIRED,false);assertEquals(0,records[0]);}
    @Test public void failedStorageStartCannotRetryOrDuplicateLater(){int[] attempts={0};AutomaticTransition t=new AutomaticTransition(new AutomaticSleep(AutomaticSleep.Mode.BEDTIME,0,1000),()->{attempts[0]++;throw new IllegalStateException("Storage unavailable");});try{t.tick(1000,true);fail();}catch(IllegalStateException expected){}t.tick(2000,true);assertEquals(1,attempts[0]);}
    @Test public void expiryDoesNotCreateAnEmptyRecord(){int[] records={0};AutomaticTransition t=new AutomaticTransition(new AutomaticSleep(AutomaticSleep.Mode.STILLNESS,0,0),()->records[0]++);assertEquals(AutomaticSleep.State.EXPIRED,t.tick(AutomaticSleep.MAX_WAIT,false));t.sample(AutomaticSleep.MAX_WAIT,.01,false);t.tick(AutomaticSleep.MAX_WAIT+1000,false);assertEquals(0,records[0]);}
    @Test public void screenTurningOnAfterQualifyingSampleRevokesTheProposal(){int[] records={0};AutomaticTransition t=new AutomaticTransition(new AutomaticSleep(AutomaticSleep.Mode.STILLNESS,0,0),()->records[0]++);for(long at=0;at<=AutomaticSleep.QUIET_REQUIRED;at+=200)t.sample(at,.01,false);assertEquals(AutomaticSleep.State.SCREEN_IN_USE,t.tick(AutomaticSleep.QUIET_REQUIRED+100,true));assertEquals(0,records[0]);}
    @Test public void staleQualifyingSignalCannotStartAfterMainLoopDelay(){int[] records={0};AutomaticTransition t=new AutomaticTransition(new AutomaticSleep(AutomaticSleep.Mode.STILLNESS,0,0),()->records[0]++);for(long at=0;at<=AutomaticSleep.QUIET_REQUIRED;at+=200)t.sample(at,.01,false);assertEquals(AutomaticSleep.State.COLLECTING,t.tick(AutomaticSleep.QUIET_REQUIRED+3000,false));assertEquals(0,records[0]);}
    @Test public void newMovementAfterQualifyingSampleRevokesTheProposal(){int[] records={0};AutomaticTransition t=new AutomaticTransition(new AutomaticSleep(AutomaticSleep.Mode.STILLNESS,0,0),()->records[0]++);for(long at=0;at<=AutomaticSleep.QUIET_REQUIRED;at+=200)t.sample(at,.01,false);t.sample(AutomaticSleep.QUIET_REQUIRED+200,.5,false);assertEquals(AutomaticSleep.State.COLLECTING,t.tick(AutomaticSleep.QUIET_REQUIRED+300,false));assertEquals(0,records[0]);}
}
